/**
 * Возвращает полный прогноз на текущую локальную дату пользователя.
 */
export function getDailyHoroscope(
  sign: ZodiacSign,
  date = new Date()
): HoroscopeSections {
  const startOfCycle = new Date(2026, 0, 1);
  const currentDay = new Date(date.getFullYear(), date.getMonth(), date.getDate());
  const elapsedDays = Math.floor(
    (currentDay.getTime() - startOfCycle.getTime()) / 86_400_000
  );
  const normalizedIndex = ((elapsedDays % 30) + 30) % 30;
  return dailyHoroscopes[normalizedIndex].horoscopes[sign];
}

/**
 * Возвращает отдельный раздел прогноза.
 */
export function getDailyHoroscopeSection(
  sign: ZodiacSign,
  section: keyof HoroscopeSections,
  date = new Date()
): string {
  return getDailyHoroscope(sign, date)[section];
}

